mapper.select:
SELECT sv.RESULT AS tabFlag, COUNT ( 1 ) AS COUNT FROM supplier_visit AS sv WHERE sv.is_deleted = FALSE
${params.permissionSql}
GROUP BY sv.RESULT

mapper.sql:
select sv.id as id, sv.create_user_id as createUserId, sv.create_user_name as createUserName, sv.create_time as createTime, sv.update_user_id as updateUserId, sv.update_user_name as updateUserName, sv.update_time as updateTime, sv.version as version, sv.is_deleted as isDeleted, sv.supplier_id as supplierId, sv.visit_type as visitType, sv.visit_time as visitTime, sv.people as people, sv.content as content, sv.result as result , s.code as supplierCode, s.name as supplierName from supplier_visit as sv left join supplier as s on sv.supplier_id = s.id and s.is_deleted = FALSE where ${params.sqlMap.default} and sv.is_deleted = FALSE
and sv.id in
#{id}
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
sv.create_time DESC
